def add_new_tile(board):
    # Add a new tile to the board
    empty_tiles = [(i, j) for i in range(4) for j in range(4) if board[i][j] == 0]
    if empty_tiles:
        i, j = random.choice(empty_tiles)
        board[i][j] = 2 if random.random() < 0.9 else 4

def draw_board(stdscr, board):
    # Clear the screen and draw the board
    stdscr.clear()
    stdscr.addstr(0, 0, "2048 Game")
    for i in range(4):
        for j in range(4):
            if board[i][j] != 0:
                stdscr.addstr(i + 1, j * 5 + 1, f"{board[i][j]:4}")
            else:
                stdscr.addstr(i + 1, j * 5 + 1, "    ")
    stdscr.addstr(6, 0, f"Score: {calculate_score(board)}")
    stdscr.addstr(7, 0, "Press 'r' to restart or any other key to continue")
    stdscr.refresh()

def calculate_score(board):
    # Calculate the current score
    return sum(sum(cell for cell in row) for row in board)

def move_tiles(board, direction):
    # Move the tiles in the specified direction
    if direction == 'up':
        board = [list(row) for row in zip(*board)]
        board = [list(row) for row in zip(*[move_row(row) for row in board])]
    elif direction == 'down':
        board = [list(row) for row in zip(*board)]
        board = [list(row) for row in zip(*[move_row(row, True) for row in board])]
    elif direction == 'left':
        board = [move_row(row) for row in board]
    elif direction == 'right':
        board = [move_row(row, True) for row in board]
    return board

def move_row(row, reverse=False):
    # Move and merge a single row
    if reverse:
        row = row[::-1]
    new_row = [0] * len(row)
    pos = 0
    for tile in row:
        if tile != 0:
            if new_row[pos] == 0:
                new_row[pos] = tile
            elif new_row[pos] == tile:
                new_row[pos] *= 2
                pos += 1
            else:
                pos += 1
                new_row[pos] = tile
    if reverse:
        new_row = new_row[::-1]
    return new_row

