        for col in range(4):
            merge_tiles(col, 0, 1)
    elif direction == 'down':
        for col in range(4):
            merge_tiles(col, 3, -1)
    elif direction == 'left':
        for row in range(4):
            merge_tiles(row, 0, 1)
    elif direction == 'right':
