from pathlib import Path
from typing import Optional, Union

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[Path, str] = Path("/tmp"),
) -> str:
    """
    Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    @param archive_path : archive file path
    @param filename: File name
    @param tmp_path: Temporary file path
    @return Repo URL
    """
    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"The archive file at {archive_path} does not exist.")

    if not archive_path.endswith('.tar'):
        raise ValueError("The archive file must be a tar file.")

    if filename is None:
        filename = os.path.basename(archive_path)

    if not isinstance(tmp_path, (Path, str)):
        raise TypeError("tmp_path must be a string or a Path object.")

    if not os.path.isdir(tmp_path):
        raise ValueError(f"The provided tmp_path '{tmp_path}' is not a valid directory.")

    tmp_dir = tempfile.TemporaryDirectory(dir=tmp_path)
    tmp_dir_path = Path(tmp_dir.name)

    try:
        with tarfile.open(archive_path, "r") as tar:
            tar.extractall(path=tmp_dir_path)
    except tarfile.Error as e:
        raise Exception(f"An error occurred while extracting the archive: {e}")

    extracted_files = list(tmp_dir_path.glob("*"))
    if not extracted_files:
        raise Exception("No files were extracted from the archive.")

    repo_url = str(extracted_files[0])
    return repo_url

