import datetime
import re
import typing

def parse_frequency(frequency: typing.Optional[str]) -> typing.Optional[datetime.timedelta]:
    if frequency is None or frequency == 'always':
        return None

    pattern = re.compile(r'^(\d+)\s*(seconds?|minutes?|hours?|days?|weeks?|months?|years?)$')
    match = pattern.match(frequency)

    if not match:
        raise ValueError("Invalid frequency string. Please use the format 'number unit' (e.g., '30 seconds').")

    number = int(match.group(1))
    unit = match.group(2)

    if unit == 'seconds':
        return datetime.timedelta(seconds=number)
    elif unit == 'minutes':
        return datetime.timedelta(minutes=number)
    elif unit == 'hours':
        return datetime.timedelta(hours=number)
    elif unit == 'days':
        return datetime.timedelta(days=number)
    elif unit == 'weeks':
        return datetime.timedelta(weeks=number)
    elif unit == 'months':
        current_date = datetime.date.today()
        first_day_of_month = datetime.date(current_date.year, current_date.month, 1)
        next_month = first_day_of_month.replace(month=current_date.month % 12 + 1)
        days_in_month = (next_month - first_day_of_month).days
        return datetime.timedelta(days=number * days_in_month)
    elif unit == 'years':
        current_date = datetime.date.today()
        first_day_of_year = datetime.date(current_date.year, 1, 1)
        next_year = first_day_of_year.replace(year=current_date.year + 1)
        days_in_year = (next_year - first_day_of_year).days
        return datetime.timedelta(days=number * days_in_year)
    else:
        raise ValueError("Unsupported time unit.")

